      "cites": ["queue-master-L00009"]
    },
    {
      "claim": "Repeated DockerSpawner failures throughout the incident window show that queue-master could not create workers, eliminating its capacity to process queued tasks.",
      "status": "confirmed",
      "cites": ["queue-master-L0000c"]
    },
    {
      "claim": "Loss of worker capacity caused tasks to backlog, resulting in sustained error logging in queue-master that reflects the user‑visible symptom of delayed or failed request processing.",
      "status": "confirmed",
      "cites": ["queue-master-L00441"]
    }
  ],
  "alternatives": [
    {
      "category": "dependency_slow",
      "service": "queue-master",
      "why_less_likely": "The logs show immediate socket‑missing exceptions rather than increased latency in queue-master's own processing, indicating a capacity loss not a slowdown.",
